const orig = $('When Called').first().json;
const impact = (orig.impact || '').trim();
const REAL_TIERS = ['Niski','Średni','Wysoki','Krytycznie ważne'];
const override = (orig.model_override != null && String(orig.model_override).trim() !== '') ? String(orig.model_override).trim() : null;

let row = null;
try { const r = $input.first().json; if (r && r.litellm_model) row = r; } catch (e) {}

let routing_default_used = false;
let routing_row_missing = false;
if (override) {
  row = { litellm_model: override, temperature: null, max_tokens: 4000, nudge: null, price_in_usd_per_1k: 0, price_out_usd_per_1k: 0, fallback_price_per_unit: null, impact: '__override__' };
} else if (!row) {
  row = { litellm_model: 'haxe-sonnet-4-6-direct', temperature: 0.7, max_tokens: 4000, nudge: null,
          price_in_usd_per_1k: 0.003, price_out_usd_per_1k: 0.015, fallback_price_per_unit: null, impact: '__fallback__' };
  if (REAL_TIERS.includes(impact)) routing_default_used = true;
  routing_row_missing = true;
} else if (row.impact === '__default__' && REAL_TIERS.includes(impact)) {
  routing_default_used = true;
}

const nudge = row.nudge ? (row.nudge + '\n\n---\n\n') : '';
const prompt = nudge + (orig.prompt || '');
const temperature = (row.temperature != null && row.temperature !== '') ? Number(row.temperature) : null;

// Multimodal (ADR-036 Block 5): content is ALWAYS an array. Image refs (ClickUp URLs from read-input)
// become image_url parts; LiteLLM fetches them. ADR-051 Block 5: image OUTPUT generation now lives only
// in Generate Images Parallel (v1); Invoke Model is text + multimodal-INPUT only.
let imgs = [];
try { imgs = JSON.parse(orig.image_blocks_json || '[]'); } catch (e) { imgs = []; }
if (!Array.isArray(imgs)) imgs = [];
const content = [{ type: 'text', text: prompt }].concat(
  imgs.filter(b => b && b.ref).map(b => ({ type: 'image_url', image_url: { url: b.ref } }))
);
const messages = [{ role: 'user', content }];
const brak = imgs.length > 0 ? '\n\n[BRAK: obraz nieczytelny na bieżącym providerze]' : '';
const messages_text_only = [{ role: 'user', content: [{ type: 'text', text: prompt + brak }] }];

// ADR-063 Block 4 (bare-lane parity): FORCE the drafting model to DELIVER its final answer by CALLING
// deliver_output, instead of emitting a free-text JSON block-array we hand-parse. LiteLLM /v1/chat/completions
// is OpenAI-shaped, so the tool is declared in OpenAI function format and forced via tool_choice; the provider
// returns the block array as message.tool_calls[].function.arguments (machine-serialized JSON), captured in
// Parse Response. KEEP IN SYNC with the managed deliver_output tool in sync-agent-definitions.json -> Build
// System (ONE schema, both lanes — ADR-063); function.parameters is the canonical ADR-063 input_schema verbatim.
const deliver_output_tool = { type: 'function', function: { name: 'deliver_output', description: "Dostarczenie FINALNEJ odpowiedzi. Wywołaj DOKŁADNIE RAZ na końcu. Parametr markdown to CAŁA odpowiedź jako zwykły tekst markdown po polsku; obrazy wstawiaj INLINE składnią ![opis](ref). NIE przekazuj tablicy JSON ani obiektów-bloków — tylko prozę markdown.", parameters: {"type":"object","properties":{"markdown":{"type":"string","description":"CAŁA finalna odpowiedź jako zwykły markdown po polsku (nagłówki, listy, tabele, pogrubienia, linki). Obrazy wstawiaj INLINE składnią ![opis](ref). NIE umieszczaj tu tablicy JSON ani obiektów-bloków."}},"required":["markdown"]} } };
const tool_choice = { type: 'function', function: { name: 'deliver_output' } };

return [{ json: {
  litellm_model: row.litellm_model,
  temperature,
  max_tokens: Number(row.max_tokens),
  price_in_usd_per_1k: Number(row.price_in_usd_per_1k || 0),
  price_out_usd_per_1k: Number(row.price_out_usd_per_1k || 0),
  prompt,
  messages,
  messages_text_only,
  had_images: imgs.length > 0,
  image_count: imgs.length,
  impact,
  task_type: orig.task_type || '',
  clickup_task_id: orig.clickup_task_id || '',
  triggered_by: orig.triggered_by || 'explicit_command',
  invocation_type: orig.invocation_type || 'explicit',
  caller_user_id: orig.caller_user_id || '',
  process_type: orig.process_type || '',
  routing_default_used,
  routing_row_missing,
  deliver_output_tool,
  tool_choice
} }];

// ADR-072 (amended): parse deliver_output(markdown) -> renderer's ordered text/image blocks by ![...](...).
// KEEP IN SYNC with services/session-waiter/lib/deliver-blocks.mjs (markdownToBlocks). Code spans / fences
// are masked so an ![](...) written inside backticks (agent documenting the contract) is not a spurious image.
function md2blocks(md){
  md = (md == null ? '' : String(md));
  var out = md.split(''), m;
  function blank(a,b){ for (var i=a; i<b && i<out.length; i++){ if (out[i] !== '\n') out[i]=' '; } }
  var fence = /(`{3,}|~{3,})[\s\S]*?\1/g; while ((m = fence.exec(md)) !== null) blank(m.index, m.index + m[0].length);
  var s2 = out.join(''), inl = /`[^`\n]*`/g; while ((m = inl.exec(s2)) !== null) blank(m.index, m.index + m[0].length);
  var masked = out.join(''), blocks = [], last = 0, order = 1, img = /!\[([^\]]*)\]\(\s*([^)\s]+)[^)]*\)/g;
  while ((m = img.exec(masked)) !== null){
    var before = md.slice(last, m.index);
    if (before.trim() !== '') blocks.push({ type: 'text', md: before.replace(/\s+$/, ''), order: order++ });
    var alt = (m[1] || '').trim(), ref = (m[2] || '').trim(), b = { type: 'image', ref: ref, order: order++ };
    if (alt !== '') { b.caption = alt; b.alt = alt; }
    blocks.push(b); last = m.index + m[0].length;
  }
  var tail = md.slice(last);
  if (tail.trim() !== '') blocks.push({ type: 'text', md: tail.replace(/^\s+/, ''), order: order++ });
  return blocks;
}

// ADR-047 Block B: read the text fallback seam (out0) OR the Retry Text-Only safety net (out1).
// $input.first() is the branch that fired (exactly one per run -> multi-input determinism).
const routing = $('Resolve Routing').first().json;
const it = $input.first() ? $input.first().json : {};

let body = {}, headers = {}, model_used = '', fell_back = false, image_unprocessable = false;
if (it && it.statusCode !== undefined) {
  // Retry Text-Only branch: routed + one-tier fallback BOTH failed -> recovered on Opus text-only.
  body = it.body || {};
  headers = it.headers || {};
  model_used = (body.model && String(body.model).trim()) ? String(body.model).trim() : 'haxe-opus-4-8-direct';
  // One WARN per sub-case: image present -> image-unprocessable WARN; no image -> degradation WARN.
  image_unprocessable = !!routing.had_images;
  fell_back = !routing.had_images;
} else {
  // Seam branch: primary OR one-tier-below fallback served.
  body = (it && it.body) ? it.body : {};
  headers = (it && it.headers) ? it.headers : {};
  model_used = (it && it.model_used) ? it.model_used : ((body.model && String(body.model).trim()) ? String(body.model).trim() : (routing.litellm_model || ''));
  fell_back = !!(it && it.fell_back);
  image_unprocessable = false;
}

const usage = body.usage || {};
const input_tokens = (usage.prompt_tokens != null) ? usage.prompt_tokens : null;
const output_tokens = (usage.completion_tokens != null) ? usage.completion_tokens : null;
// ADR-063 Block 4: the drafting model is FORCED (tool_choice) to call deliver_output; its block array arrives
// as message.tool_calls[].function.arguments — machine-serialized JSON (NOT model-hand-written prose), so a
// single JSON.parse replaces the deleted free-text parseBlockArray (the entire defect class is gone). Falls
// back to message.content as a text block only if the model somehow returned no deliver_output call.
let completion = '';
let output_blocks = [];
let delivered_via_tool = false;
try {
  const msg = (body.choices && body.choices[0] && body.choices[0].message) || {};
  const calls = Array.isArray(msg.tool_calls) ? msg.tool_calls : [];
  const tc = calls.find(function (c) { return c && c.function && c.function.name === 'deliver_output'; }) || calls[0] || null;
  if (tc && tc.function && tc.function.arguments != null) {
    let args = tc.function.arguments;
    if (typeof args === 'string') args = JSON.parse(args);
    // ADR-072 (amended): deliver_output carries scalar markdown; split it into the renderer's block array.
    if (args && args.markdown != null) { output_blocks = md2blocks(args.markdown); delivered_via_tool = true; }
  }
  if (!delivered_via_tool) completion = msg.content || '';
} catch (e) { try { completion = body.choices[0].message.content || ''; } catch (e2) {} }
const ch = headers['x-litellm-response-cost'];
const usd_cost = (ch != null && ch !== '') ? Number(ch) : null;

// Header (usd_cost) is authoritative; price columns are a dormant backup. On a fallback the served
// model may differ from the routed row, but for text the header is reliably present, so keep the
// routed (primary) prices as the rough backup rather than hardcoding a model-specific price.
const provider = String(model_used).includes('gemini') ? 'litellm/vertex' : 'litellm/anthropic-direct';

return [{ json: {
  completion,
  output_blocks_json: JSON.stringify(output_blocks),
  delivered_via_tool,
  model_used,
  provider,
  input_tokens, output_tokens, usd_cost,
  price_in_usd_per_1k: routing.price_in_usd_per_1k,
  price_out_usd_per_1k: routing.price_out_usd_per_1k,
  routing_default_used: !!routing.routing_default_used,
  routing_row_missing: !!routing.routing_row_missing,
  fell_back: fell_back,
  image_unprocessable,
  images_dropped: image_unprocessable ? (routing.image_count || 0) : 0,
  impact: routing.impact,
  task_type: routing.task_type,
  clickup_task_id: routing.clickup_task_id,
  triggered_by: routing.triggered_by,
  invocation_type: routing.invocation_type,
  caller_user_id: routing.caller_user_id,
  process_type: routing.process_type
} }];
